import{_ as t,o as a,c,a0 as o}from"./chunks/framework.BLL-IG04.js";const u=JSON.parse('{"title":"Explanation: architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),d={name:"explanation/architecture.md"};function i(r,e,n,s,l,h){return a(),c("div",null,[...e[0]||(e[0]=[o('<h1 id="explanation-architecture" tabindex="-1">Explanation: architecture <a class="header-anchor" href="#explanation-architecture" aria-label="Permalink to &quot;Explanation: architecture&quot;">​</a></h1><h2 id="claims-not-opinions" tabindex="-1">Claims, not opinions <a class="header-anchor" href="#claims-not-opinions" aria-label="Permalink to &quot;Claims, not opinions&quot;">​</a></h2><p>Docs and memory cards make <em>claims</em>: this path exists, this command works, this symbol lives here, this number is current. mimus extracts claims into a taxonomy — each type routes to the checker that can actually prove or refute it:</p><table tabindex="0"><thead><tr><th>claim</th><th>checker</th><th>tier</th></tr></thead><tbody><tr><td><code>path</code></td><td><code>check-fs</code></td><td>mechanical</td></tr><tr><td><code>command</code></td><td><code>check-cmd</code></td><td>mechanical</td></tr><tr><td><code>symbol</code></td><td><code>check-symbol</code> (kuda)</td><td>mechanical</td></tr><tr><td><code>count</code></td><td><code>check-cmd</code>/<code>check-fs</code></td><td>mechanical</td></tr><tr><td><code>link</code></td><td><code>check-link</code> (planned)</td><td>mechanical</td></tr><tr><td><code>behavior</code></td><td><code>check-llm</code> (planned)</td><td>semantic</td></tr></tbody></table><h2 id="the-evidence-bar" tabindex="-1">The evidence bar <a class="header-anchor" href="#the-evidence-bar" aria-label="Permalink to &quot;The evidence bar&quot;">​</a></h2><p>A violation is claim + evidence + suggested fix. No evidence, no finding — false positives kill a critic faster than false negatives. The semantic tier can never gate CI: it reports, a human adjudicates. Style opinions are never emitted at all.</p><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p>Every concern is a trait crate + adapter crates: checkers (<code>fs</code> | <code>cmd</code> | <code>symbol</code> | <code>llm</code>), claim sources (md, comments, cards), sinks (cli, commit-status). Rules are data (<code>rules/*.toml</code>) — conventions as files, not code.</p><h2 id="position-in-the-ecosystem" tabindex="-1">Position in the ecosystem <a class="header-anchor" href="#position-in-the-ecosystem" aria-label="Permalink to &quot;Position in the ecosystem&quot;">​</a></h2><ul><li><code>kuda</code> builds the index; <code>mimus</code> doubts it — <code>audit</code> trust-scores cards against source via the <code>symbol</code> checker.</li><li><code>reconcile</code> (planned third tool) auto-fixes what mimus confirms: claims rewritten to match reality.</li></ul>',10)])])}const p=t(d,[["render",i]]);export{u as __pageData,p as default};
